    def lengthOfLongestSubstring(self, s: str) -> int:
        char_idx = {}
        left = 0
        longest = 0
        for right, ch in enumerate(s):
            if ch in char_idx and char_idx[ch] >= left:
                left = char_idx[ch] + 1
            char_idx[ch] = right
            longest = max(longest, right - left + 1)
        return longest

